// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":186,"question":"أنا شابٌّ قادرٌ على الحج، ولم أحجّ حجة الإسلام، وأبي يمنعني من الحجِّ، فما حكم قعودي وحكم رفض والدي للحج؟","title":"ماذا يفعل من يمنعه أبوه من حج الفريضة؟","answer":"الجواب: عليه أن يحجَّ ولو منعه أبوه، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لا طاعةَ لمخلوقٍ في معصية الخالق، لكن يُخاطبه بالتي هي أحسن، يقول: يا والدي، أنا الحمد لله قادرٌ، وهذا فرضٌ عليَّ، والذي مثلك يُعينني على الخير، وكذلك يستعين بأعمامه أو إخوانه أو جيرانه الطيبين حتى يرضى والده، فإن أصرَّ فلا طاعةَ له. لكن ما أظن مسلمًا يُصرُّ على هذا إن كان فيه خيرٌ، ما يُصرُّ، فولده قادرٌ ويمنعه من الحجِّ؟! هذا ما يكون من مؤمنٍ، إنما يكون من فاسقٍ أو كافرٍ، ولكن إن أصرَّ على هذا مع الكلام الطيب معه ومع نصيحته فلا طاعةَ له، يحجُّ ولا عليه.","link":"https://binbaz.org.sa/fatwas/3759/ماذا-يفعل-من-يمنعه-ابوه-من-حج-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0189.mp3","categories":["حكم الحج والعمرة"]},{"id":188,"question":"شخصٌ أتى بالحج، ثم بعد الحجِّ يأتي بعمرةٍ من التَّنعيم، فما قولك في هؤلاء الذين يكثرون؟","title":"حكم أداء العمرة عقب الانتهاء من الحج","answer":"الجواب: إن كانوا ما اعتمروا سابقًا عمرة الفريضة؛ يعتمروا بعد الحجِّ، وإن كانوا قد اعتمروا يكفيهم، لا يُشوشوا على الناس، ولا يُزاحموهم، تكفي والحمد لله؛ لأنَّ بعد الحج فيه زحمة شديدة، فالأوْلى بالمؤمن إذا كان قد اعتمر ألا يُزاحم الناس، وألا يشقَّ على الناس وعلى نفسه، يُوسِّع للناس.\nوالصحابة مع النبيِّ ﷺ ما اعتمر أحدٌ بعد فراغهم من نُسكهم، وتوجهوا إلى المدينة، ما اعتمر الرسولُ وأصحابه، كلهم لم يعتمروا إلَّا عائشة فقط، فعائشة طلبت من النبيِّ ﷺ فأعمرها، وإلا فالصحابة ذكر العلماءُ أنهم لم يعتمر أحدٌ منهم بعد الحجِّ، ولا النبي ﷺ، ولنا فيهم أسوة.\nفالأفضل ترك ذلك؛ لأنَّ هذا يُفضي إلى المُزاحمة والمشقَّة، إلا إنسانٌ ما اعتمر سابقًا -ما اعتمر في الإسلام- فيعتمر بعد الحجِّ، وإذا تيسر له أن يتراخى حتى يخفَّ الناسُ فحسنٌ.","link":"https://binbaz.org.sa/fatwas/3761/حكم-اداء-العمرة-عقب-الانتهاء-من-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0192.mp3","categories":["حكم الحج والعمرة"]},{"id":393,"question":"هل يجوز تعدد العمرة أكثر من مرة في الشهر؟ وما الدليل؟","title":"هل يجوز تكرار العمرة في شهر واحد؟","answer":"الجواب: لم يُحدد الشارع عليه الصلاة والسلام شيئًا بين العمرتين، ولم يثبت عنه ﷺ أنه حدد شيئًا، فمَن حدد فعليه الدليل، والرسول عليه الصلاة والسلام قال: العمرة إلى العمرة كفَّارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة، فلم يحدد، فالدليل يُطلب ممن حدَّد، لا ممن لم يُحدد.","link":"https://binbaz.org.sa/fatwas/4778/هل-يجوز-تكرار-العمرة-في-شهر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0449.mp3","categories":["حكم الحج والعمرة"]},{"id":615,"question":"إذا كان الشاب قادرًا على أن يحج وأخّر الحج إلى أن يتزوج أو يكبر في السن هل يأثم، أحسن الله إليك؟","title":"حكم تأجيل الحج مع الاستطاعة للزواج وغيره","answer":"الجواب: يأثم إذا استطاع يأثم، إذا بلغ وهو يستطيع يأثم، يجب عليه البِدار، ومن يضمن؟ قد يموت قبل ذلك، إذا بلغ؛ وَجَب عليه الحج.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6455/حكم-تاجيل-الحج-مع-الاستطاعة-للزواج-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/maram183 - 01 -  Start.mp3","categories":["حكم الحج والعمرة"]},{"id":624,"question":"من العلماء من يفرق بين المكي وغير المكي، يقول أن المكي لا تجب عليه العمرة؟","title":"ما صحة أن المكي لا تجب عليه العمرة؟","answer":"الجواب: هذا قول ضعيف ليس عليه دليل، الأدلة عامة.","link":"https://binbaz.org.sa/fatwas/6490/ما-صحة-ان-المكي-لا-تجب-عليه-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/maram192 - 03 - .mp3","categories":["حكم الحج والعمرة"]},{"id":1229,"question":"هل وجوب الحجِّ على الفور أم على التَّراخي؟","title":"هل وجوب الحج على الفور أم على التّراخي؟","answer":"الجواب:\nالصواب من قولي العلماء أنه على الفور، هذه قاعدة في أوامر الله: أنها على الفور، إلا إذا دلَّ الدليلُ على التَّراخي، وإلا فهي على الفور، فالحج على الفور، والصلاة على الفور في أوقاتها، والصيام في وقته كذلك، وهكذا إذا كان مُستطيعًا لا يُؤخِّر؛ لأنه أوجب عليه الحج، فالواجب البِدار إلى أداء الواجب.","link":"https://binbaz.org.sa/fatwas/21283/هل-وجوب-الحج-على-الفور-ام-على-التراخي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1026هل وجوب الحج على الفورأم على التراخي؟ ابن باز.mp3","categories":["حكم الحج والعمرة"]},{"id":1239,"question":"هل على أهل مكة عمرة؟","title":"هل على أهل مكة عُمرة؟","answer":"الجواب:\nنعم، الصواب عليهم عمرة مثل غيرهم، لكن لا يكون متمتعًا، إذا اعتمر ما عليه دم العمرة، عليه عمرة مرة في العمر؛ لما ثبت في حديث عمر في سؤال جبرائيل أنه قال عليه الصلاة والسلام لجبرائيل: الإسلام: أن تشهد أن لا إله إلا الله وأنَّ محمدًا رسول الله، وتُقيم الصلاة، وتُؤتي الزكاة، وتصوم رمضان، وتحج، وتعتمر خرجه ابن خُزيمة والدارقطني بإسنادٍ صحيحٍ، ولقوله ﷺ في حديث عائشة لما قالت: يا رسول الله، نرى الجهادَ أفضل الأعمال، قال: عليكنَّ جهادٌ لا قتالَ فيه: الحج والعمرة، فهذا يشمل أهلَ مكة وأهلَ المدينة وغيرهم، والصواب أنَّ عليهم عمرةً مرةً في العمر كغيرهم.","link":"https://binbaz.org.sa/fatwas/21296/هل-على-اهل-مكة-عمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1039هل على أهل مكة عمره؟ ابن باز.mp3","categories":["حكم الحج والعمرة"]},{"id":1248,"question":"هل يجوز أن يعتمر الرجلُ في اليوم أكثر من عمرةٍ؟ وإذا كان يجوز وهو في مكة من أين يُحرم؟","title":"هل يجوز عمل أكثر من عمرة في يوم واحد؟","answer":"الجواب:\nلم يأتِ التَّحديد فيما نعلم فيما بين العمرتين، لكن الأفضل ألا يُكرر، إذا كان يُؤذي الناس مع الحجاج الكثيرين لا يُكرر؛ حتى لا يُؤذي أحدًا، والرسول عليه السلام قال: العمرة إلى العمرة كفَّارةٌ لما بينهما، فلا يُكرر إذا كان يُؤذي الناس.  أما إذا كان ما يُؤذي أحدًا في وقت السّعة؛ فليس فيما بين العمرتين حدٌّ محدودٌ على الراجح. وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21306/هل-يجوز-عمل-اكثر-من-عمرة-في-يوم-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1049هل يجوز أن يعتمر الرجل في اليوم أكثر من عمرة؟ ابن باز.mp3","categories":["حكم الحج والعمرة"]},{"id":1690,"question":"أقول: مثل أهل مكة مثلًا: السفر قريب للحج، ولو عليه دَيْنٌ لا يحج؟","title":"حكم حج مَن كان من أهل مكة وعليه دَيْن","answer":"الجواب:\nلا، يبدأ بالدَّين، فالواجب عليه أن يبدأ بالدين، إلا إذا كان أهلُ الدَّين معروفين وسامحوه، أو يحجُّ على حساب غيره، ما يضُرُّهم، وليسوا مُنفقين شيئًا؛ فلا بأس.\nس: السفر من مكة إلى عرفة قريب يعني: الحج ما يُكَلِّف شيئًا؟\nج: المقصود: إذا كان سفرُه لا يضُرُّ الدَّائنين فلا بأس.\nس: إذا كان قريبًا؟\nج: قريبًا أو بعيدًا، إذا لم يكن يضرُّهم فلا بأس.\nس: يعني: ليست العِلَّة في السفر: أنه يُخْشَى عليه؟\nج: العِلَّة في الضَّرر، فعليه أن يُعْطِي النفقةَ التي يُنفقها في الحجِّ للدَّائنين.\nس: يعني: ليست العِلَّةُ في السفر؟\nج: لا، ليست العلةُ في السفر، العلة أنَّهم أولى بنفقة الحج.","link":"https://binbaz.org.sa/fatwas/21796/حكم-حج-من-كان-من-اهل-مكة-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حج من كان من مكة وعليه دين.mp3","categories":["حكم الحج والعمرة"]},{"id":1956,"question":"الحج واجب على الفور؟","title":"هل فرض الحج على الفور أم التراخي؟","answer":"الجواب:\nهذا الصواب، هذا الراجح، فيه خلاف، لكن الراجح أنه على الفور إذا توافرت الشروط، إذا وُجِدَ الماء يعني.","link":"https://binbaz.org.sa/fatwas/22071/هل-فرض-الحج-على-الفور-ام-التراخي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحج على الفور أم على التراخي.mp3","categories":["حكم الحج والعمرة"]},{"id":3113,"question":"مَنْ ترك الحج وهو مستطيع هذه كبيرة؟","title":"حكم مَنْ ترك الحج وهو مستطيع","answer":"الجواب: الأظهر أنها كبيرة، لأن الله قال: وَمَنْ كَفَرَ.. [آل عمران:97] يعني ضيّع الحج، ترك الحج مع الاستطاعة هذا أمر عظيم ومنكر عظيم.","link":"https://binbaz.org.sa/fatwas/23273/حكم-من-ترك-الحج-وهو-مستطيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من ترك الحج وهو مستطيع.mp3","categories":["حكم الحج والعمرة"]},{"id":3146,"question":"أصدرت الدولة حفظها الله أوامر بعدم الحج إلى السعودية إلا بتصاريح، وفيه واحد والده متوفى وموصيه أن يحج خمس حجج له ولوالدته، وهو طبعا بيسلسلها، وطلع القرار، هذا هل لو حج بطريقته الخاصة بدون ما يأخذ أمرًا؟","title":"حكم حَجِّ مَنْ لا يملك تصريح الحج","answer":"الجواب: لاـ يتبع القرار، هذا صادر من هيئة كبار العلماء، الدولة أحالته إلى هيئة كبار العلماء لأجل التخفيف على الحجاج.\nس: لو حج، في حجه شيء؟\nالشيخ: يحج مثل ما في القرار. إذا كان قد حج خمس مرات يصبر، يحج ويقول هذه الحجة لأبيه، ما هي له، إذا حج لأبيه ما يخالف.","link":"https://binbaz.org.sa/fatwas/23308/حكم-حج-من-لا-يملك-تصريح-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة حج من لا يملك تصريح الحج.mp3","categories":["حكم الحج والعمرة"]},{"id":3178,"question":"تعامل الشركة هذه مع عمال المسلمين، ولا يجوز لهم نظامًا أن يحجوا إلا بعد كل خمس سنوات، فيقولون: نعطي معقب الشركة مالًا فنستطيع أن نحج كل سنة.....؟","title":"حكم مَنْعِ حَجِّ الموظف إلا بعد خمس سنوات","answer":"الجواب: الشيخ: ويش نعطي؟\nس: نعطي \"فلوس\".\nالشيخ: بقشيش؟\nس: أي نعم؛ تسهل لنا أمورنا.\nالشيخ: لا لا، يجب التمشي مع التعليمات؛ لأن مقصود الدولة التخفيف على الحجاج، هذا صدر فيه قرار من هيئة كبار العلماء بأنه لا بأس به لأجل مصلحة الحجاج، مصلحة المسلمين، الذي قد حج الفريضة الحمد لله.\nس: يُذكر لهم التحريم؟\nالشيخ: ما يجوز.","link":"https://binbaz.org.sa/fatwas/23341/حكم-منع-حج-الموظف-الا-بعد-خمس-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شركة تمنع موظفيها من الحج إلا بعد كل خمس سنوات.mp3","categories":["حكم الحج والعمرة"]},{"id":4386,"question":"ذهب الإنسان من الرياض إلى مكة للعمرة بنية عمرة واحدة، وبعدما اعتمر فكر بالعمرة الثانية، فهل يجوز له ذلك، وإذا كان يجوز من أين يحرم بالعمرة؟","title":"هل يجوز تكرار العمرة؟ ومن أين يحرم؟","answer":"الجواب: لا حرج إذا اعتمر ثم أراد أن يعتمر عن أبيه الميت أو أمه أو نحو ذلك يخرج إلى التنعيم أو الجعرانة أو عرفات، يعني إلى الحل ويحرم بالعمرة الجديدة من الحل خارج الحرم، كما اعتمرت عائشة بأمر النبي من التنعيم عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24663/هل-يجوز-تكرار-العمرة-ومن-اين-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز تكرار العمرة، ومن أين يحرم للعمرة الثانية.mp3","categories":["حكم الحج والعمرة"]},{"id":4633,"question":"مَنْ يثبِّط عن الحج بحجة الزحام؟","title":"حكم مَنْ يترك الإكثار من الحج لتخفيف الزحام","answer":"الجواب: قد يكون له وجه؛ إذا اشتدَّ الزحام ورأى أنَّ يُنفِّس على مسلمٍ، قد يكون له وجه إذا كان قد أكثر الحجَّ، ليس ببعيدٍ. وأما الأصل شرعية الاستكثار من الحج والعمرة، هذا هو الأصل، لكن إذا ترك ذلك بنيةٍ صالحةٍ نرجو له الخير.","link":"https://binbaz.org.sa/fatwas/24923/حكم-من-يترك-الاكثار-من-الحج-لتخفيف-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يثبط عن الحج بحجة الزحام.mp3","categories":["حكم الحج والعمرة"]},{"id":4635,"question":"حديث أحمد: تعجَّلوا إلى الحجِّ يعني الفريضة؟","title":"ما دلالة حديث \"تعجَّلوا إلى الحجِّ\"؟","answer":"الجواب: في إسناده رجلٌ يقال له: إسماعيل بن خليفة، قال الحافظ فيه: إنه سيئ الحفظ. لكن العمدة على غيره، العمدة على الآية الكريمة: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ.. [آل عمران:97]، وحديث: إنَّ الله كتب عليكم الحجَّ فحجُّوا، هذه واضحة، الأمر على الفور، هذا الأصل، الأوامر على الفور إلا ما دلَّ الدليل على التراخي فيه.","link":"https://binbaz.org.sa/fatwas/24925/ما-دلالة-حديث-تعجلوا-الى-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث تعجَّلوا إلى الحجِّ.mp3","categories":["حكم الحج والعمرة"]},{"id":4649,"question":"إذا أتى الرجلُ إلى مكة ولم يُرد العمرة، ولكنه لم يسبق له أن اعتمر عمرة الإسلام، هل يلزمه الإحرام؟","title":"حكم الحج والعمرة لمن أتى مكة لأول مرة","answer":"الجواب: يخرج إلى الحلِّ ويُحرم وتكفيه عن عمرة الإسلام.\n...  يلزمه أن يُؤدي عمرة الإسلام.\nس: يعني في هذه الحالة يجب عليه ولو ما أراد؟\nج: إذا أتى مكةَ وما بعد اعتمر يلزمه، أو جاء مكة وقت الحجِّ؛ يلزمه الحج؛ لأنه استطاع.\nس: ولو قال: ما أريد الآن، أريد في وقتٍ آخر؟\nج: لا. يلزمه.","link":"https://binbaz.org.sa/fatwas/24939/حكم-الحج-والعمرة-لمن-اتى-مكة-لاول-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى تكون العمرة واجبة على العبد.mp3","categories":["حكم الحج والعمرة"]},{"id":4674,"question":"قوله: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ يشمل حتى الصغار؟","title":"هل يجب على الصغار إتمام الحج والعمرة؟","answer":"الجواب: يشمل الذين أدخلهم أولياؤهم، أما هم فلا، ما يلزمهم شيء إذا كانوا بأنفسهم، لكن إذا أدخلهم وليُّهم هو محلّ كلام أهل العلم، إذا أدخلهم لزمه أن يُتمم بهم الذين دون السبع، أما إذا أحرموا بأنفسهم فلهم التَّحلل، لكن ينبغي له أن يُعلِّمه حتى يُكمل؛ لأنهم ليس عليهم فريضة، وقد يقال بوجوب الإتمام؛ لأنهم دخلوا فيه: كالحاج المتنفل، والمعتمر المتنفل، لو أنَّ الإنسان حجَّ مُتنفلًا أو اعتمر مُتنفلًا لزمه الإتمام، وقد يُقال في حقِّ الصبيان: إنَّ على وليهم أن يُلزمهم بالإتمام؛ لأنهم هم الذين أدخلوا، وإن كانوا غير مُكلَّفين، لكن بشيء عارض، مثلما يُمنعون من المعاصي وإن كانوا غير مُكلَّفين؛ لئلا يتلاعبوا، فالقول بهذا قول وجيه، لكن الأصل أنه لا يلزمهم، غير مُكلَّفين، لكن إذا دخلوا عُقلاء قد بلغوا السبعَ -هم من جهتهم دخلوا- ينبغي لوليِّهم أن يُؤكِّد عليهم أن يُكملوا، وإذا أدخلهم هو وهم دون السبع يلزمه، هو الذي يُكمل بهم؛ لأنه مسؤولٌ عنهم، كما يكفُّهم عن المحارم.","link":"https://binbaz.org.sa/fatwas/24966/هل-يجب-على-الصغار-اتمام-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ هل يشمل حتى الصغار.mp3","categories":["التفسير","حكم الحج والعمرة"]},{"id":5213,"question":"سماحة الشيخ: أنا شابٌّ قادرٌ على الحج، ولم أحجّ حجة الإسلام، وأبي يمنعني من الحجِّ، فما حكم قعودي وحكم رفض والدي للحج؟","title":"ما حكم من يستطيع الحج ولكن يمنعه والده؟","answer":"الجواب: عليه أن يحجَّ ولو منعه أبوه، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لا طاعةَ لمخلوقٍ في معصية الخالق، لكن يُخاطبه بالتي هي أحسن، يقول: يا والدي، أنا الحمد لله قادرٌ، وهذا فرضٌ عليَّ، والذي مثلك يُعينني على الخير، وكذلك يستعين بأعمامه أو إخوانه أو جيرانه الطيبين حتى يرضى والده، فإن أصرَّ فلا طاعةَ له، لكن ما أظن مسلمًا يُصرُّ على هذا إن كان فيه خيرٌ، ما يُصرُّ، فولده قادرٌ ويمنعه من الحجِّ! هذا ما يكون من مؤمنٍ، إنما يكون من فاسقٍ أو كافرٍ، ولكن إن أصرَّ على هذا مع الكلام الطيب معه ومع نصيحته؛ فلا طاعةَ له، يحجُّ ولا عليه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/30157/ما-حكم-من-يستطيع-الحج-ولكن-يمنعه-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 189.mp3","categories":["حكم الحج والعمرة"]},{"id":5216,"question":"يقول: شخصٌ أتى بالحج، ثم بعد الحجِّ يأتي بعمرةٍ من التَّنعيم، فما قولك في هؤلاء الذين يُكثرون..؟","title":"ما حكم الإتيان بعمرة بعد إكمال الحج؟","answer":"الجواب: إن كانوا ما اعتمروا سابقًا عمرة الفريضة يعتمروا بعد الحجِّ، وإن كانوا قد اعتمروا يكفيهم، لا يُشوشوا على الناس، ولا يُزاحموهم، تكفي والحمد لله؛ لأنَّ بعد الحج فيه زحمة شديدة، فالأولى بالمؤمن إذا كان قد اعتمر ألا يُزاحم الناس، وألا يشقَّ على الناس وعلى نفسه، يُوسِّع للناس. والصحابة مع النبيِّ ﷺ ما اعتمر أحدٌ بعد فراغهم من نُسكهم، وتوجهوا إلى المدينة، ما اعتمر الرسولُ وأصحابه، كلهم لم يعتمروا إلَّا عائشة فقط، فعائشة طلبت من النبيِّ ﷺ فأعمرها، وإلا فالصحابة ذكر العلماءُ أنهم لم يعتمر أحدٌ منهم بعد الحجِّ، ولا النبي ﷺ، ولنا فيهم أسوة. فالأفضل ترك ذلك؛ لأنَّ هذا يُفضي إلى المُزاحمة والمشقَّة، إلا إنسانٌ ما اعتمر سابقًا -ما اعتمر في الإسلام- فيعتمر بعد الحجِّ، وإذا تيسر له أن يتراخى حتى يخفَّ الناسُ؛ فحسنٌ.","link":"https://binbaz.org.sa/fatwas/30160/ما-حكم-الاتيان-بعمرة-بعد-اكمال-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 192.mp3","categories":["حكم الحج والعمرة"]},{"id":5273,"question":"هل يلزم قضاء الدين قبل أداء العمرة؟","title":"هل يجب قضاء الدين قبل الحج والعمرة؟","answer":"الجواب: إذا كان عنده القدرة بوفاء الدين يؤدي العمرة، وإذا كان ليس عنده قدرة يبدأ بالدَّين، لأن الدَّين واجب والعمرة مستحبة، فمن كان عليه ديون فنفقات العمرة يجعلها لبعض الغرماء. س: إذا كان صاحبه يمهله؟ الشيخ: إذا كان صاحبه محدودًا، شخصًا أو شخصين، ما يخالف. س: الحج أيضا كذلك؟ الشيخ: والحج كذلك.[1]","link":"https://binbaz.org.sa/fatwas/30886/هل-يجب-قضاء-الدين-قبل-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 014.mp3","categories":["حكم الحج والعمرة"]},{"id":5393,"question":"حجَّ ثم ارتد، هل يلزمه الحج مرةً ثانيةً؟","title":"هل يجب الحج على من حجَّ ثم ارتد؟","answer":"الجواب: لا، ما يلزمه، إذا هداه الله وأسلم فحجه باقٍ. س: تفسير الآية: كَالَّتِي نَقَضَتْ غَزْلَهَا مِنْ بَعْدِ قُوَّةٍ [النحل:92]؟ ج: ما ذكره الله جل وعلا يُبيّن حالَ الناس الذين هم على خيرٍ ثم ينقضون أعمالَهم بالردة، فتبطل أعمالُهم بردَّتهم، كالتي نقضت غزلها. س: لو حج رياءً، وهي حجَّة الفريضة، تلزمه الإعادة؟ ج: الحج رياء باطل.[1]","link":"https://binbaz.org.sa/fatwas/31136/هل-يجب-الحج-على-من-حج-ثم-ارتد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 009.mp3","categories":["حكم الحج والعمرة"]},{"id":5474,"question":"إذا ابتدأ الحج لغير الله، ثم عرض له الإخلاص في عرفة أو قبل الطواف؟","title":"ما حكم مَن ابتدأ الحج بنيةٍ لغير الله؟","answer":"الجواب: الذي يظهر لي إذا صار أساس الحجِّ لغير الله؛ عليه الإتمام؛ لأنَّ الله قال: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]، لكن نيته لغير الله تُبطل ثوابه، ما يكون له ثواب الحجِّ، عليه وزر؛ وزر الشرك الأصغر.\nس: هل يجب عليه الإتمام مع أنَّ أصل العبادة لغير الله؟\nج: ولو، مأخوذ بدخوله، دعواه أنه نوى كذا ما يُسلم له، يجب الإتمام، الله قال: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ.\nس: أليست الآيةُ مناطةً بمَن ابتدأ الحجَّ لله ، مناط قوله تعالى: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّه فيمن ابتدأها لله، بينما الحج الفاسد لعارض يعرض عليه، هذا ابتدأها لله لكن عرض له الوطء وغيره فأمر بإتمامه؟\nج: إذا ابتدأها لغير الله، تحتاج إلى تأملٍ.[1]","link":"https://binbaz.org.sa/fatwas/31360/ما-حكم-من-ابتدا-الحج-بنية-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al_moaqeyn 001.mp3","categories":["حكم الحج والعمرة"]},{"id":7531,"question":"سماحة الشيخ! هذه رسالة تتعلق بالحج، يقول المرسل أخوكم في الله جابر يحيى الشوفي المالكي رجل له مدة طويلة ولم يحج، مع أنه يملك الزاد والراحلة، ويزعم أنه لا يستطيع الحج، فما حكمه؟","title":"حكم تأخير الحج مع الاستطاعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن حج بيت الله الحرام فرض على كل من استطاع السبيل إليه، من الرجال والنساء؛ لقول الله سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97].\nفالذي يملك الزاد والراحلة، يملك القدرة على أداء الحج ثم يتخلف قد أتى كبيرة عظيمة، ومنكراً عظيماً، فالواجب عليه التوبة إلى الله والبدار للحج في أول فرصة تمكنه، وليس له التخلف عن ذلك أو التساهل في ذلك، مادام يستطيع الحج ببدنه وماله، وهذا أمر مجمع عليه بين أهل العلم ليس فيه خلاف، بل قد أجمع العلماء على وجوب الحج مع الاستطاعة على جميع المكلفين من الرجال والنساء، إذا استطاع ذلك ببدنه وماله. نعم.","link":"https://binbaz.org.sa/fatwas/4517/حكم-تاخير-الحج-مع-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01101.mp3","categories":["حكم الحج والعمرة"]},{"id":7532,"question":"هذه الرسالة من المرسل (م. ع. م) بريدة القصيم يقول: قمت بتأدية فريضة الحج في إحدى السنين حجاً مفرداً، وكما هو معلوم بقيت محرماً بعد طواف القدوم حتى رمي جمرة العقبة يوم النحر عشرة ذي الحجة، ثم الحلق والتحلل الأول، وأكملنا مناسك الحج؛ الطواف والإفاضة، يقول: وعندما سألنا عن حقيقة هذا الحج طلب منا أداء عمرة لمن لم يسبق له أداؤها، وفعلاً أدينا هذه العمرة من التنعيم، ما حكم من حج مفرداً بدون عمرة، هل هي واجبة لتمام الحج أم لا؟ نرجو الإيضاح وفقكم الله؟","title":"حكم العمرة على من جمع مفردًا","answer":"الجواب: الحج مفرداً صحيح، والعمرة لابد منها، فإن ضمها إلى الحج وحج قارناً أجزأ ذلك وكفى، فإن حج حجاً مفرداً .... أحرم بالحج وبقي على إحرامه حتى كمل مناسك الحج فإنه يحتاج إلى عمرة بعد ذلك، من التنعيم أو غير التنعيم، من الحل يعني، التنعيم أو من الجعرانة أو غيرهما من الحل، فإذا أدى ذلك بأن أحرم من الجعرانة أو من التنعيم فطاف وسعى وقصر وحلق، تمت عمرته والحمد لله.\nوالعمرة واجبة في أصح قولي العلماء؛ لأنه ورد عن النبي ﷺ ما يدل على ذلك، ومنها أنه لما سأله جبرائيل عن الإسلام ذكر له: أنه شهادة أن لا إله إلا الله، وأن محمداً رسول الله، قال: وأن تقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت وتعتمر، فذكر العمرة في بيان الإسلام، فدل على فرضيتها، وقد روى هذا الحديث بهذه الزيادة ابن خزيمة في صحيحه وجماعة بإسناد صحيح. نعم.","link":"https://binbaz.org.sa/fatwas/4518/حكم-العمرة-على-من-جمع-مفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01102.mp3","categories":["حكم الحج والعمرة"]},{"id":8032,"question":"سماحة الشيخ عبد العزيز! هذه رسالة يقول مرسلها من الدمام من المنطقة الشرقية راشد محمد الراشد:إذا شفي المعذور بعد أن تلبس نائبه بالحج، فهل يقع الحج عن فريضة الإسلام أم يكون نفلاً في حقه؟","title":"حكم من شفي من مرضه بعد حج نائبه عنه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا شفي المعذور مما سوغ النيابة عنه في الحج فقد اختلف العلماء رحمة الله عليهم: هل يجزئ ذلك المعذور الحج، أم عليه أن يأتي به لزوال العذر، على قولين مشهورين لأهل العلم، والأحوط للمؤمن في مثل هذا أنه يأتي بالحج؛ لأن الأكثر من أهل العلم على أن عليه أن يأتي بالحج؛ لأنه اتضح أن عذره غير ميئوس منه، غير ميئوس من زواله، وكان الأصل في إباحة النيابة أن العذر يظهر أنه ميئوس منه وأنه كالشيخ الكبير الذي لا حيلة في عود الشباب إليه؛ فلهذا جازت النيابة عنه، فهذا المعذور الذي زال عذره واتضح أن مرضه ليس بميئوس من زواله، فينبغي له أن يأتي بالحج كسائر المسلمين الذين لا عذر لهم، وهذا هو الأحوط له وفيه خروج من خلاف العلماء، وفيه العمل بقول الأكثرين، والله سبحانه وتعالى أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5640/حكم-من-شفي-من-مرضه-بعد-حج-ناىبه-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_079/07901.mp3","categories":["حكم الحج والعمرة"]},{"id":8386,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: وبعد: أحيط جنابكم علماً بأني مدرس تونسي، مقيم بالمملكة، أطلب من سيادتكم إجابتي على الأسئلة التالية:أولاً: هل تجزئ العمرة في شهر رمضان المعظم عن الحج؛ لقول الرسول ﷺ: من اعتمر في رمضان كان كمن حج معي.","title":"عدم إجزاء العمرة في رمضان عن الحج","answer":"الجواب: لا تجزئ العمرة في رمضان عن الحج، ولكنها يكون لها فضل الحج؛ لقوله ﷺ: عمرة في رمضان تعدل حجة، أو قال: حجة معي يعني: في الأفضل والأجر، وليس معناه: أنها تعدلها، وتقوم مقامها، حتى لا يكون عليه حج، لا؛ بل عليه الحج، حجة الإسلام وإن اعتمر في رمضان، عند جميع أهل العلم، فالعمرة في رمضان يحصل بها فضل الحج، من جهة الفضل ومن جهة الأجر، ولكنها لا تجزئ عن حجة الإسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6252/عدم-اجزاء-العمرة-في-رمضان-عن-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11605.mp3","categories":["حكم الحج والعمرة"]},{"id":8387,"question":"يسأل أخونا سؤال آخر، ويقول: إن والدتي عمرها خمس وستون سنة، وزوجتي ست وعشرون سنة، وتقيمان في تونس، أوصتا بأن أعتمر مكانهما، فهل يجوز ذلك؟","title":"حكم الاعتمار عن الوالدة والزوجة مع القدرة وعدمها","answer":"الجواب: ليس لك أن تعتمر عنهما، بل عليهما أن يعتمرا إذا أعانهما الله على ذلك ويسر لهما ذلك، لكن لو كانت أمك عاجزة لكبر السن لا تستطيع الحج والعمرة، فلك أن تعتمر عنها وتحج عنها إذا كانت عاجزة؛ لأن الرسول ﷺ سئل، سألته امرأة، فقالت: يا رسول الله! إنن أبي شيخ كبير، لا يثبت على الراحلة، أفأحج عنه؟ قال: حجي عن أبيك فإذا كانت أمك عاجزةً لا تستطيع الحج ولا العمرة، فإنك تعتمر عنها وتحج عنها، ولا بأس.\nوهكذا لو كانت الأم ميتة، أو الأب ميت، لا بأس أن تحج عنهما وتعتمر. نعم.","link":"https://binbaz.org.sa/fatwas/6253/حكم-الاعتمار-عن-الوالدة-والزوجة-مع-القدرة-وعدمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11606.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":8484,"question":"الأعرج والحج تسأل عن الحكم سماحة الشيخ، الأعرج هل عليه أن يحج أم أن ذلك يسقط عنه بسبب عرجه؟","title":"عدم سقوط الحج عن الأعرج والأعمى","answer":"","link":"https://binbaz.org.sa/fatwas/6543/عدم-سقوط-الحج-عن-الاعرج-والاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12511.mp3","categories":["حكم الحج والعمرة"]},{"id":8744,"question":"هل يجوز للمسلم أن يقوم في اليوم الواحد بأداء العمرة خمس مرات، يطوف ويسعى ويرجع إلى الميقات ويحرم من جديد، وهلم جرا؟","title":"حكم تكرار العمرة في اليوم الواحد عدة مرات","answer":"الجواب: ليس هذا من عمل السلف الصالح، والأفضل ترك ذلك لما فيه من المشقة ولما فيه من المزاحمة للناس، ولا سيما وقت الحج وقت الزحمة، والنبي ﷺ قال: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة فمراده ﷺ يقول: العمرة إلى العمرة كفارة لما بينهما والله أعلم يعني: على وجه لا يكون فيه مشقة ولا مضرة على الناس؛ ولهذا كان السلف لا يفعلون ذلك، ما كان السلف يعتمرون عمرتين في اليوم أو في الليلة، بل كان بينهما بعض الوقت؛\nفالأحسن والأفضل أنه يترك العمرة وقت الزحمة، فإذا كان سعة اعتمر حسب التيسير من دون أن يفعل ذلك مكررًا في كل يوم، بل يكون بينهما فسحة كما كان السلف يفعلون، ويحمل قول النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما على الشيء المعتاد المعروف الذي يكون بينهما بعض الفصل، بعض الوقت ككل أسبوع عمرة، أو كل شهر شهر عمرة أو كل نص شهر عمرة أو نحو ذلك من دون متابعة في اليوم الواحد، ولا سيما عند كثرة الحجيج فإن هذا يشق على الناس كثيرًا، والصحابة  ومعهم النبي ﷺ لم يعتمروا بعدما فرغوا من الحج، بل لما فرغ من الحج ودع عليه الصلاة والسلام ليلة أربعة عشر ثم غادر مكة وسافر إلى المدينة عليه الصلاة والسلام ولم يكرر العمرة، وهكذا الصحابة لما حلوا من العمرة في أربعة ذي الحجة لم يبلغنا أن أحدًا منهم توجه إلى العمرة في تلك الأيام الأربعة يعتمر ثانيًا، لم يبلغنا ذلك ولو فعلوه لنقل إلينا إلى المسلمين.\nفالحاصل أنه لا مانع من تكرار العمرة في الشهر مرات أو في الأسبوع، لكن على وجه لا يضر الحجيج ولا يشق على الناس ولا يشق على المعتمر نفسه، بل يراعي في ذلك الآداب الشرعية التي سار عليها سلف الأمة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6896/حكم-تكرار-العمرة-في-اليوم-الواحد-عدة-مرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16207.mp3","categories":["حكم الحج والعمرة"]},{"id":8777,"question":"يقول: هل العمرة تسقط الفريضة إذا أديت في غير أشهر الحج؟","title":"حكم العمرة في غير أشهر الحج","answer":"الجواب: نعم؛ متى أدى المسلم أو المسلمة العمرة في أي شهر سقطت عنه العمرة الواجبة، فإذا أداها في شعبان أو في جمادى أو في صفر أو في غير ذلك صح ذلك وكفت وسقط بها الواجب، سواءً كان المؤدي امرأة أو رجلاً. نعم..\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6932/حكم-العمرة-في-غير-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21905.mp3","categories":["حكم الحج والعمرة"]},{"id":9189,"question":"أخ سوداني أيضاً مقيم في المملكة يقول: (أ. أ. ح) أخونا يسأل عن العمرة في رمضان ويقول: ألاحظ أن كثيراً من الناس يحرصون على تأدية العمرة في رمضان والبعض يكررها في هذا الشهر الكريم ولاسيما في العشر الأواخر، حدثونا لو تكرمتم عن مشروعية هذا العمل وعن تكرار العمرة بالنسبة للفرد ولاسيما في العشر الأواخر كما ذكرت ؟","title":"حكم تكرار العمرة في رمضان","answer":"الجواب: أسباب ذلك أنه صح عن النبي ﷺ أنه قال: عمرة في رمضان تعدل حجة، وفي الرواية الأخرى: تعدل حجة معي يعني: معه عليه الصلاة والسلام، فلهذا ينافس المسلمون في ذلك ويحرصون على أداء العمرة في رمضان رغبة في هذا الأجر العظيم، وإذا كررها في رمضان مرتين أو ثلاث فلا بأس من أجل هذا الخير العظيم، لكن ينبغي له أن يلاحظ أن لا يشق على الناس، فإذا كان في زحمة كبعض الليالي العشر الأخيرة، فالأقرب عندي والأظهر عندي ترك ذلك حتى يوسع للناس مادام اعتمر في أول الشهر فالحمد لله؛ حتى لا تحصل في عمرته وأمثاله المضايقة للناس الذين لم يعتمروا في أول الشهر.\nفالحاصل أن المؤمن يراعي حال إخوانه الذين يعتمرون في العشر الأخيرة، فإذا كان في وقت تحصل فيه شدة فينبغي له أن يوسع لهم وأن يكتفي بالعمرة السابقة التي حصلت له في أول الشهر أو في أثنائه والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7349/حكم-تكرار-العمرة-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15104.mp3","categories":["حكم الحج والعمرة"]},{"id":9414,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن الجنوبي، وباعثتها إحدى الأخوات من هناك تقول المستمعة إيمان، أختنا تقول: إذا أردت أداء فريضة الحج وامتنع والدي فهل أطيعه أم أذهب للسفر؟","title":"حكم طاعة الوالد في عدم الذهاب لأداء فريضة الحج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله  فرض على عباده حج بيته الحرام، وجعله أحد أركان الإسلام الخمسة، حيث قال عليه الصلاة والسلام في الحديث الصحيح: بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت متفق على صحته، وثبت في الصحيح أيضاً من حديث عمر بن الخطاب رضي الله تعالى عنه: أن جبرائيل عليه الصلاة والسلام سأل النبي ﷺ عن الإسلام؟ فقال: الإسلام أن تشهد أن لا إله إلا الله وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً.\nوالله يقول في كتابه الكريم وهو أصدق القائلين: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَنْ كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ عَنِ الْعَالَمِينَ [آل عمران:97].\nفالواجب على جميع المكلفين من المسلمين المستطيعين لأداء الحج أن يحجوا، مرة واحدة في العمر؛ لأنه ﷺ سئل عن ذلك، فقال عليه الصلاة والسلام: الحج مرة فما زاد فهو تطوع.\nفإذا كنت -أيها السائلة- قادرة على الحج من جهة المال فليس لوالدك أن يمنعك، ولا يجوز لك طاعته في ذلك؛ لقول النبي ﷺ: إنما الطاعة في المعروف، وقال عليه الصلاة والسلام: لا طاعة لمخلوق في معصية الخالق.\nفالواجب عليه أن يساعد في هذا، وأن يفرح بحجك، وأن يعينك على ذلك، أما المنع فليس له منعك، إذا تيسر لك محرم يسافر معك من أخ أو زوج أو عم أو خال أو غيرهم من المحارم.\nوعليك أن تجتهدي في الأخذ بخاطره واستسماحه، والتوصل إلى ذلك بمن ترين من الأقارب حتى لا يكون بينك وبين والدك شيء، وهو إذا كان مسلماً سوف يرضى وسوف يرجع إلى الصواب إن شاء الله، ونسأل الله لك وله التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/7579/حكم-طاعة-الوالد-في-عدم-الذهاب-لاداء-فريضة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19001.mp3","categories":["حكم الحج والعمرة"]},{"id":9717,"question":"تقول هذه السائلة في آخر أسئلتها: أديت العمرة أنا ووالدي ودفع لنا تكاليف العمرة والسفر زوجي، فهل تقبل عمرة والدي؟","title":"حكم العمرة إذا كانت مئونتها من الغير","answer":"الجواب: نعم إن شاء الله إذا أخلص فيها واجتهد تقبل إن شاء الله، ولو أن زوجك ساعد في ذلك، إذا أخلص أبوك وأنتم في هذا واجتهدتم في طاعة الله والخشوع لله، وطلبه القبول، فهو سبحانه جواد كريم، إذا تقبل منكم فله الفضل ، ولو كان الزوج هو الذي بذل النفقة، إذا أخلصتم لله وصدقتم في أداء العمرة واجتهدتم في ذلك رغبةً ورهبة فأنتم على خير عظيم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7872/حكم-العمرة-اذا-كانت-مىونتها-من-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27210.mp3","categories":["حكم الحج والعمرة"]},{"id":9904,"question":"هذه سائلة يا سماحة الشيخ رمزت لاسمها بـ (ن. س) من الرياض تقول: هل صحيح أن من مات ولم يحج وهو قادر على ذلك يكون نصرانيًا أو يهوديًا، وإذا كان كذلك تقول: فهي فتاة تود أن تؤدي فريضة الحج، ولكن جميع أفراد الأسرة قد أدوا هذه الفريضة عندما كانت صغيرة، فماذا تفعل، تقول: وأنا لا أجد من يحججني، هل علي إثم؟ وهل على أسرتي إثم في ذلك؟ جزاكم الله خيراً.","title":"حكم من ترك الحج وهو قادر والمرأة إذا لم تجد محرماً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحج فريضة على كل مسلم مكلف مستطيع من الرجال والنساء مرة واحدة في العمر؛ لقول الله جل وعلا: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] ومن تركه وهو قادر فهو على خطر، وقد روي عن علي  أنه قال فيمن تركه وهو قادر: لا عليه أن يموت يهوديًا أو نصرانيًا وهذا من باب الوعيد، هذا من باب التحذير والوعيد وإلا فليس بكافر، من تركه ليس بكافر لكنه عاصي إذا ترك الحج وهو يستطيع، تركه تساهلًا فهو عاصٍ، ويروى عن عمر أنه قال: ما هم بمسلمين، ما هم بمسلمين  والمقصود من هذا كله التحذير والترهيب من التساهل وإلا فالذي ترك الحج وهو مستطيع قد عصى ولكنه ليس بكافر، بل هو مسلم يصلى عليه ويدفن في مقابر المسلمين، وإذا لم يكن لديك محرم فليس عليك حج حتى يتيسر المحرم أخ أو أب أو عم أو خال وإذا كانت المرأة لا تجد محرماً فلا شيء عليها، والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8072/حكم-من-ترك-الحج-وهو-قادر-والمراة-اذا-لم-تجد-محرما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27316.mp3","categories":["حكم الحج والعمرة"]},{"id":10347,"question":"رسالة المستمع من السودان (د. ح. ج. أ) عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: وفقني الله وأديت فريضة الحج مفرداً ولكن لم أعتمر، وذلك لعدة ظروف وقفت في طريقي، فهل حجي مقبول، أفيدوني جزاكم الله خيراً؟","title":"حكم من حج مفرداً ولم يعتمر","answer":"الجواب: نعم الحج مستقل حجك صحيح والحمد لله، وعليك أن تعتمر في المستقبل إذا كنت لم تعتمر سابقاً لا في رمضان ولا في غيره، فالواجب عليك -في أصح قولي العلماء: أن تعتمر في أي وقت، العمرة مالها وقت محدود، لكن عليك أن تعتمر في رمضان أو في غيره من الشهور، متى يسر الله لك ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8516/حكم-من-حج-مفردا-ولم-يعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33806.mp3","categories":["حكم الحج والعمرة"]},{"id":10766,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، وباعثها مستمع من هناك رمز إلى اسمه بالحروف (ع. ب. س) يقول: أنا شاب أبلغ من العمر ثمانية عشر عاماً طالب في المدرسة ثالث ثانوي، ولي والدة تبلغ من العمر حوالي ثمانية وخمسين عاما، والدي متوفى منذ خمسة عشر عاماً، وأريد والدتي أن تذهب إلى الحج ولكنها تقول: إن ذلك لا يجوز وهو حرام حتى تتزوج، أرجو من سماحتكم إفادتي، إذ والدتي تفضل تزويجي قبل أدائها للحج، وجهونا حول هذا الموضوع جزاكم الله خيراً.","title":"حكم تقديم الحج على الزواج والعكس","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فلا شك أن الحج فرض على كل إنسان استطاع السبيل إليه؛ لقول الله : وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]، فإذا كنت تستطيع الحج من جهة المال وجب عليك الحج، وإذا كانت تستطيع الحج هي من جهة المال وجب الحج، وإن بدأت بالزواج؛ لأنك بحاجة إلى الزواج فلا حرج؛ لأن الزواج أيضاً فرض مع الشهوة والرغبة فيه، لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء.\nوبكل حال: لا بأس أن تقدم الحج على الزواج وقول أمك: إنه حرام غلط منها، عفا الله عنا وعنها، لا بأس بالحج بل عليك أن تحج إذا استطعت الحج، ولك أن تقدم الزواج إذا كنت ترغب في الزواج، وتخشى على نفسك من مضرة التأخير وخطر التأخير، وهي كذلك إذا كان المراد حجها هي فإنها تحج أيضاً ولو قبل زواجه، إذا كانت تستطيع الحج أو أنت تستطيع الحج حتى تحججها من مالك، فإنها لا حرج عليها أن تحج قبل أن تتزوج هي وقبل أن تتزوج أنت، حتى ولو حجت وهي أيم ما تزوجت كذلك، أو أنت إذا كان قصدها أنت لا بأس أن تحج هي قبل أن تتزوج أنت.\nفالمقصود أن الكلام هذا ليس في محله غلط، فلك أن تتزوج أنت ولها أن تتزوج هي ولا حرج في ذلك، أما تأجيل الحج حتى تتزوج أنت أو حتى تتزوج هي هذا لا أصل له، بل هذا جائز وهذا جائز، وإذا كانت تستطيع الحج ولم تحج هي فعليها أن تحج بعد خروجها من العدة إذا كانت ... مع أن أباك قد مات من مدة طويلة عليها أن تحج إذا كانت تستطيع الحج، وأنت عليك أن تحج إذا استطعت الحج ولو قبل الزواج، وإذا أردت أن تقدم الزواج فلا حرج في ذلك، الأمر في هذا واسع؛ لأن هذا واجب وهذا واجب، مع الشهوة إذا كنت تشتهي النكاح وتخشى على نفسك، فإن قدمت النكاح فلا بأس وإن قدمت الحج فلا بأس، وعليك أن تقنعها وتوجهها إلى الخير وتعلمها بما سمعت الآن، ولعلها تسمع أيضاً هذا البرنامج وتستفيد في هذا الباب وترجع عن قولها. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرا، مفهوم الرسالة كما فهمت سماحة الشيخ! أن الوالدة هي التي تمتنع عن الحج حتى يتزوج ابنها؟\nالشيخ: كله لا وجه له، سواءً كان المراد هي أو المراد الولد، على كل حال لها أن تحج هي وإن لم يتزوج ولدها، وله أن يحج قبل الزواج، وليس شرطاً أن يقدم الزواج، لكن إذا احتاج إلى الزواج وخاف على نفسه وقدم الزواج فلا حرج. نعم.\nالمقدم: جزاكم الله خيراً، لعلها تريد توفير النفقة لزواج ابنها؟\nالشيخ: قد يكون هذا لكن لا يجوز أن ..... حرام، لا تقل: حرام، لو قالت يعني: نحب أن نزوجك وينبغي أن نبدأ بك ... من باب يعني تقديم الزواج على الحج هذا لا بأس إذا دعت الحاجة إلى ذلك. نعم.\nالمقدم: لكن لا تقل: حرام.\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8941/حكم-تقديم-الحج-على-الزواج-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34801.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":10851,"question":"في كلمة أخيرة صغيرة لو سمحتم سماحة الشيخ: الحج والعمرة للمحادة؟","title":"حكم الحج والعمرة للمحادة","answer":"الجواب:  لا تحج، ولا تعتمر؛ لأنها ممنوعة من الخروج إلا لحاجة، تبقى في بيتها تعتد ..... وإذا انتهت تحج -إن شاء الله- ثم أمر آخر وهو إذا انتهت من الإحداد بعض العامة يقول لها: تسوي كذا، وتسوي كذا، تدخل للمسجد، أو تلبس خاتمًا صفته كذا أو كذا، كل هذا لا أصل له. إذا انتهت من الإحداد تغير إما بملابس أخرى، أو تتطيب، أو نحو ذلك مما يدل على أنها خرجت من الإحداد، يعني: تغير مما يشير، ويدل على أنها انتهت بتغيير الملابس إلى ملابس أحسن منها، تتطيب، تكحل كل هذا يكفي، أما أنها تخرج إلى المسجد، أو زيارة أحد معين، أو ... ما له أصل، متى خرجت تخرج متى شاءت تخرج، وإذا سافرت كذلك للحج أو العمرة بعد خروجها من العدة لا بأس.  أما في حال الإحداد في حال العدة لا، لا تسافر لا حج، ولا عمرة.","link":"https://binbaz.org.sa/fatwas/9032/حكم-الحج-والعمرة-للمحادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35613.mp3","categories":["حكم الحج والعمرة"]},{"id":11029,"question":"هل العمرة في شهر رجب لها مزية عن بقية الشهور؟","title":"حكم العمرة في رجب","answer":"الجواب:  كان السلف يفعلونها، لا حرج فيها، وثبت عن عمر أنه كان يعتمر في رجب، وابن عمر، وذكر ابن سيرين أن السلف كانوا يفعلونها كما قال ابن رجب -رحمه الله- في اللطائف، وثبت عن ابن عمر أن النبي ﷺ اعتمر في رجب، ولكن المشهور عند أهل العلم أن الرسول ﷺ اعتمر في ذي القعدة، كل عمره في ذي القعدة، هذا المعروف عند أهل العلم، أن عُمَرَ النبي ﷺ في ذي القعدة، لا في رجب، لكن فعلها عمر  وبعض الصحابة، وفعلها كثير من السلف لا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9207/حكم-العمرة-في-رجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28711.mp3","categories":["حكم الحج والعمرة"]},{"id":11499,"question":"يسأل أيضًا سؤالًا فيقول: ما الحكم في شاب لم يتزوج، ولكنه ينوي الحج، هل حجه صحيح؟","title":"تقديم الحج على الزواج","answer":"الجواب: نعم حجه صحيح إذا كان ما تزوج، ولو كان بنية الزواج، إذا قدم الحج وحج؛ حجه صحيح إذا أداه كما شرح الله، حجه صحيح ولو ما تزوج، الحج يصح من العزب ومن المتزوج، الحمد لله، نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/9683/تقديم-الحج-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38316.mp3","categories":["حكم الحج والعمرة"]},{"id":11839,"question":"سماحة الشيخ! لعله من المناسب أن تتفضلوا بتوجيه الناس إلى قضية هل الحج يجب على الفور، أم على التراخي؟","title":"مسألة وجوب الحج على الفور أو التراخي","answer":"الجواب:  الحج يجب على الفور، هذا هو الصواب الذي عليه جمهور أهل العلم، الحج يجب المبادرة به على الفور، إذا كان قادرًا ببدنه وماله، وأما إذا كان عاجزًا بالمال؛ فلا حج عليه، أو عاجزًا بالبدن لمرض يؤجل حتى يشفى، أما القادر بماله وبدنه فإن الواجب عليه البدار بالحج والمسارعة إليه، لقول الله سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] وَلِلَّهِ عَلَى النَّاسِ [آل عمران:97] يعني: واجب لله على الناس. فالواجب البدار بذلك هذا هو الواجب، على الرجل والمرأة والأعرابي والحضري على جميع المسلمين، يجب عليهم الحج ولو كانوا في أطراف الدنيا في الشرق والغرب، يجب عليهم أن يحجوا إذا استطاعوا بالمال والبدن، فإن لم يستطع ببدنه لكبر سنه، أو مرض لا يرجى برؤه، فإنه يجب عليه أن يستنيب من الثقات الطيبين من يحج عنه ممن قد حج عن نفسه، النائب لابد أن يكون قد حج عن نفسه، سواءً كان رجلًا أو امرأة، وهكذا العاجز لكبر السن كونه كبير السن ما يستطيع يستنيب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10022/مسالة-وجوب-الحج-على-الفور-او-التراخي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39602.mp3","categories":["حكم الحج والعمرة"]},{"id":11842,"question":"سماحة الشيخ! بعض الناس يتشاغل بأمور وأمور عن الحج، فقد يتشاغل ببناء مسكن، ويتشاغل بالزواج، أو شراء السيارة، وما أشبه ذلك، هل من كلمة؟","title":"نصيحة لمن اشتغل بالدنيا عن الحج","answer":"الجواب:  نعم لا يجوز للمؤمن أن يتشاغل عن الحج الواجب، من استطاع الحج الواجب عليه البدار بالحج، ولا يجوز له التشاغل ببناء مسكن، أو شراء مزرعة، أو ما أشبه ذلك. أما الزواج فله شأن آخر، إذا احتاج للزواج، وخاف على نفسه؛ يبدأ بالزواج؛ لأنه من النفقة اللازمة، فإذا احتاج للزواج، وخاف على نفسه من تأخير الزواج؛ يبدأ به قبل الحج، ثم يحج بعد ذلك، أما إذا كان لا يخشى؛ فإنه يبدأ بالحج. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا من ملك عقارًا، كبيوت ومزارع وهو لم يؤد فريضة الحج بعد يعتبر مخطئ؟ الشيخ: نعم لا يجوز له التشاغل، عليه التوبة إلى الله من تأخيره، وعليه المبادرة بالحج. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، وهذا يشمل البعيد والقريب بطبيعة الحال؟ الشيخ: نعم ولو في أمريكا، أو في أي مكان، أو في روسيا، أو في أي مكان، في أي مكان من الأرض يلزمه السعي إذا استطاع ذلك، نعم. المقدم: أحسن الله إليكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/10023/نصيحة-لمن-اشتغل-بالدنيا-عن-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39603.mp3","categories":["حكم الحج والعمرة"]},{"id":12338,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها مستمع يقول: أخوكم في الله هايل مسحم محمد أبو المهدي يقول: بالنسبة إلى العمرة لقد وفقني الله وبعض الإخوة لزيارة مكة المكرمة من أجل أداء مناسك العمرة، وحيث إنني أديت العمرة عن نفسي، وثلاث عمرات أخرى أوهبتها للوالدين، وزوجتي بالترتيب، وكنت في كل عمرة أتحلل، وأذهب للتنعيم للإحرام بالأخرى، وحيث أن هذا العمل كان موضع جدال بيني وبين الإخوة من ناحية جوازه، الرجاء الإفادة عن هذا العمل، وعن طريقته وحكمه، وجوازه؟ جزاكم الله خيرًا.","title":"حكم تكرار العمرة، وإهداء ثوابها للغير","answer":"الجواب:  الصواب: أنه لا بأس بذلك، لقول النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة متفق على صحته، ولم يحدد مدة بين العمرتين، لكن إذا كان المقام فيه مضايقة للحجاج، وفيه أذى وزحمة؛ فالأولى ترك ذلك إلى وقت السعة، أما إذا كان الوقت فيه سعة، وليس فيه إيذاء لأحد؛ فلا حرج في ذلك -إن شاء الله-إذا كان المعتمر عنهم ميتين، أو عاجزين، لا يستطيعون على العمرة، ولا الحج لكبر السن، أو مرض لا يرجى برؤه، نعم. المقدم: جزاكم الله خيرًا، وإذا كانوا أقوياء سماحة الشيخ؟ الشيخ: لا لا يعتمر عنهم، ولا يحج عنهم، ... أقوياء .. لا يحج عنهم، ولا يعتمر عنهم، وإنما الحج والعمرة عن إنسان كبير السن، لا يستطيع الحج، أو مريض لا يرجى برؤه. المقدم: بارك الله فيكم، من فعل ذلك سماحة الشيخ؟ الشيخ: في الحج لا، من فعل الحج عمن لا يستحق، من فعل حجًا أو عمرة عمن لا تجزئ عنه؛ صار له، صارت حجته له. المقدم: ما شاء الله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10544/حكم-تكرار-العمرة-واهداء-ثوابها-للغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39903.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":12385,"question":"مستمع يقول أحمد لطفي محمد يقول: أنا رجل أعزب، ولست متزوجًا، وأبلغ من العمر الثانية والثلاثين، هل أبدأ بالحج، أم بالزواج؟ جزاكم الله خيرًا.","title":"الأفضلية في تقديم الحج على الزواج والعكس","answer":"الجواب:  إذا كنت في حاجة للزواج، وتخشى على نفسك؛ فابدأ بالزواج، والحج بعدين، بعد الزواج تحج إذا استطعت، أما إذا كنت لا تخشى الفتنة، ولا تخشى على نفسك من تأخير الزواج؛ فابدأ بالحج، ثم تزوج بعد ذلك. المقصود: أنك تراعي ما هو الخطر، ما هو الذي يضرك وتخشى منه، فإن كان النكاح يضرك تأخيره، وتخشى على نفسك؛ فابدأ بالنكاح. وإن كنت لا تخشى شيئًا، وتخشى أن يفوت عليك الحج؛ فبادر بالحج، والحمد لله، اعمل بما هو أقل ضررًا، وأكثر نفعًا، وأنت أعلم بنفسك، أنت أعلم بنفسك، فإذا كنت في حاجة للزواج، وتخشى على نفسك من التأخير؛ فابدأ بالزواج، وإن كنت -بحمد الله- لا تخشى شيئًا، بل أنت مطمئن أنه لا شيء عليك، ولا يضرك التأخير؛ فابدأ بالحج، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10586/الافضلية-في-تقديم-الحج-على-الزواج-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40105.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":12628,"question":"يقول في سؤال آخر: وفقني الله -والحمد لله- على أداء فريضة الحج، ولكني لم أستطع أن أعتمر عمرة الحج؛ لأنني كنت قد نويت الحج والعمرة مفردًا، وبعد أن أديت الحج، حدثت لي عدة ظروف لم أستطع أن أعتمر، ورجعت من حيث أتيت، فهل في هذه الحالة يعتبر حجي صحيحًا؟","title":"حكم من حج مفردًا ولم يعتمر","answer":"الجواب:  نعم الحج صحيح، والحمد لله، وإذا كنت لم تكن تعتمر سابقًا تعتمر بعد ذلك متى تيسر لك الأمر، تسافر إلى مكة وتعتمر، إذا كنت لم تعتمر سابقًا، أما إن كنت قد اعتمرت سابقًا؛ فالحمد لله، العمرة مرة في العمر، وهكذا الحج مرة في العمر، والباقي نافلة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10838/حكم-من-حج-مفردا-ولم-يعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41502.mp3","categories":["حكم الحج والعمرة"]},{"id":12657,"question":"المستمع محمد أحمد إسماعيل من جمهورية مصر العربية يقول: أنا أعزب، وأريد أن أحج بيت الله الحرام، هل يكون حجي صحيحًا قبل أن أتزوج؟","title":"حكم حج الإنسان قبل زواجه","answer":"الجواب:  نعم، لك أن تحج، بل يجب عليك أن تحج إذا كنت قادرًا، ولو لم تتزوج، الحج يجب مع الاستطاعة على الأعزب وغير الأعزب، من استطاع السبيل إليه؛ وجب عليه الحج، وإن كان لم يتزوج، ولكن يجب عليك البدار بالزواج إذا استطعت؛ لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج فعليك أن تبادر قبل الحج من حين تستطيع، فإذا أخرت، ولم تبادر؛ وجب عليك الحج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10867/حكم-حج-الانسان-قبل-زواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45809.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":12737,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع: (ن. أ. ن) يقول: نعمل بمزرعة في مكة المكرمة لمدة عام ونصف، ولم أحج، فما رأيكم سماحة الشيخ إذا لم يوافق كفيلي بذهابي للحج، في العام القابل، هل أحج بدون إذنه؟ وجهوني جزاكم الله خيرًا.","title":"موقف العامل إذا رفض صاحب العمل ذهابه إلى الحج","answer":"الجواب:  الواجب عليك أن تحج إذا استطعت ذلك؛ لأن الله يقول سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] فعليك أن تفعل ما تستطيع حتى تؤدي هذه الحجة التي فرضها الله عليك، وإذا دعت الحاجة إلى أن ترفع الأمر إلى سمو أمير منطقة مكة، أو نائبه حتى يقنع كفيلك بالسماح لك بالحج؛ فذلك ممكن، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10951/موقف-العامل-اذا-رفض-صاحب-العمل-ذهابه-الى-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41808.mp3","categories":["حكم الحج والعمرة"]},{"id":12874,"question":"المستمع: أحمد حسوبة بعث يسأل ويقول: بلغت من العمر خمسة وأربعين عامًا، وذهبت إلى الحج، وقضيت المناسك كلها، هل لي حجة، أم لا؛ لأني لم أتزوج بعد؟","title":"حكم الحج لمن لم يتزوج","answer":"الجواب:  ليس الزواج من شرط الحج، الحج يصح من له زوجه، ومن ليس عنده زوجة، حجك إذا كنت أديت حقه، حجك صحيح، ولو كنت ما تزوجت، فالنكاح ليس بشرط في الحج، وليس الحج شرطًا في النكاح، كل منهما ليس شرطًا في الآخر، يحج قبل الزواج، وبعد الزواج، ويتزوج قبل الحج، أو بعد الحج، كل هذا -والحمد لله- أمره واسع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11089/حكم-الحج-لمن-لم-يتزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46606.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":13075,"question":"يقول هذا السائل يا سماحة الشيخ: الشخص الذي عليه دين هل تلزمه فريضة الحج؟","title":"حكم الحج على من عليه دين","answer":"الجواب:  إذا كان عنده قدرة على الدين والحج؛ تلزمه، أما إن كان ما عنده قدرة؛ يبدأ بالدين، ولا حج عليه، لكن إن كان عنده مال يستطيع يوفي الدين، ويستطيع يحج؛ يلزمه الحج؛ لأن الله قال: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] فإذا كان عنده أموال يستطيع يوفي الدين، ويستطيع يحج؛ وجب عليه، أما إن كان ماله بقدر الدين، أو أقل من الدين؛ لا يلزمه الحج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11292/حكم-الحج-على-من-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50707.mp3","categories":["حكم الحج والعمرة"]},{"id":13076,"question":"في فقرة أخرى يقول هذا السائل: الشاب الغير متزوج أيهما أفضل الحج، أم الزواج؟","title":"مسألة تقديم الحج على الزواج والعكس","answer":"الجواب:  إن كان يستطيعهما؛ فعلهما جميعًا، يتزوج ويحج جميعًا، فإن كان المال لا يتسع إلا لأحدهما، فإن كان محتاجًا للزواج يخشى على نفسه؛ بدأ بالزواج، فإن كان لا يهمه الزواج؛ لأن شهوته ضعيفة لا يخشى خطرًا؛ بدأ بالحج، وأدى حج الفريضة، أما إن كان لا؛ يخشى على نفسه؛ فإنه يبدأ بالزواج، ومتى أيسر حج بعد ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11293/مسالة-تقديم-الحج-على-الزواج-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50708.mp3","categories":["حكم الحج والعمرة"]},{"id":13224,"question":"تقول السائلة: إذا أدى الحاج مناسك الحج مفردًا، فهل عليه بعد أن يكمل المناسك أن يذهب إلى التنعيم، ويحرم بعمرة بعد الحج، وما معنى قوله تعالى: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]؟","title":"حكم الإتيان بعمرة على من حج مفرداً","answer":"الجواب:  إذا كان ما اعتمر يعتمر، إذا كان لم يعتمر سابقًا، وأحرم بحج وحده؛ فإنه إذا فرغ من الحج يعتمر من التنعيم كما فعلت عائشة، أمرها النبي ﷺ أن تعتمر من التنعيم بعد حجها، أما إذا كان قد اعتمر سابقًا؛ فالحمد لله، يكفيه عمرته السابقة، والحمد لله. وأما قوله: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] معناه: إذا لبى بهما يتمهما، إذا لبى بالحج يتمه بأركانه وواجباته، وإذا لبى بالعمرة كذلك يتمها بطوافها، وسعيها، وحلقها، أو تقصيرها إن كان رجلًا، أو بالطواف والسعي والتقصير إن كانت مرأة، لابد من تمامها؛ لأنها بالشروع وجبت، إذا شرع بالعمرة؛ وجب إتمامها، إذا شرع في الحج؛ وجب إتمامه، ولو كان نافلة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11503/حكم-الاتيان-بعمرة-على-من-حج-مفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52011.mp3","categories":["حكم الحج والعمرة"]},{"id":13286,"question":"في آخر أسئلة هذا السائل مصري، ومقيم بالرياض يقول: سماحة الشيخ! ذهبت من الرياض لأداء العمرة، والحمد لله أديتها كما يجب أن تكون، ثم خلعت ملابس الإحرام، وفي اليوم الثاني ذهبت إلى مسجد التنعيم؛ لكي أحرم من هناك، وأنوي عمرة لوالدتي المتوفية، وبالفعل نويت العمرة، ووهبتها إلى والدتي، فهل هذه العمرة صحيحة؟ وجزاكم الله خيرًا.","title":"حكم العمرة عن الغير بعد العمرة عن النفس مباشرة","answer":"الجواب: لا حرج -إن شاء الله- لقوله ﷺ: العمرة إلى العمرة كفارة لما بينهما ولم يشترط أيامًا معلومة بينهما، فالحديث عام، فإذا اعتمر الإنسان لنفسه، وفرغ من عمرته، ثم ذهب إلى التنعيم، واعتمر لأبيه الميت، أو الهرم الذي لا يستطيع، أو لأمه، أو لغيرهما من الأموات، أو لعجزهم لكبر السن؛ فلا بأس. لكن إذا كان زحمة كأيام الحج؛ فالأفضل أن يكتفي بعمرة واحدة، حتى يخفف على الناس، ولا يشق عليهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11571/حكم-العمرة-عن-الغير-بعد-العمرة-عن-النفس-مباشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51413.mp3","categories":["حكم الحج والعمرة"]},{"id":13562,"question":"هل العمرة في أشهر الحج فيها شيء من الإلزام بالحج، أو غيره كما قال بعض الناس؟","title":"هل يلزم الحج على من اعتمر في أشهر الحج؟","answer":"الجواب: لا. لكن الأفضل العمرة في ذي القعدة كما اعتمر النبي ﷺ وفي رمضان، وإذا كان اعتمر مرة كفى، الواجب مرة واحدة، الحج مرة، والعمرة مرة بس، وما زاد هو سنة نافلة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11897/هل-يلزم-الحج-على-من-اعتمر-في-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52212.mp3","categories":["حكم الحج والعمرة"]},{"id":13564,"question":"هل العمرة في أشهر الحج فيها شيء من الإلزام بالحج، أو غيره كما قال بعض الناس؟","title":"هل يلزم الحج على من اعتمر في أشهر الحج؟","answer":"الجواب: لا. لكن الأفضل العمرة في ذي القعدة كما اعتمر النبي ﷺ وفي رمضان، وإذا كان اعتمر مرة كفى، الواجب مرة واحدة، الحج مرة، والعمرة مرة بس، وما زاد هو سنة نافلة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11897/هل-يلزم-الحج-على-من-اعتمر-في-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52212.mp3","categories":["حكم الحج والعمرة"]},{"id":13566,"question":"هذا السائل الذي أرسل بمجموعة من الأسئلة لم يكتب الاسم في هذه الرسالة يقول: أحببت أن أذهب إلى العمرة، ولكن ينقصني المال الحلال الصافي، فهل يجوز أن أذهب على نفقة الجامعة، أو على نفقة الوزارة -جزاكم الله خيرًا- أو على نفقة والدي إذ أن ماله مخلوط من الحلال والحرام؟ جزاكم الله خيرًا.","title":"حكم الذهاب إلى العمرة على نفقة الآخرين","answer":"الجواب: لا حرج في ذلك، أن تذهب على حساب الجامعة، أو على حساب بعض المحسنين، أو على حساب والدك، لا حرج في ذلك، ولكن إذا تيسر لك مال طيب سليم تنفقه على نفسك؛ كان أطيب وأكمل، إذا تيسر لك مال من كسبك، طيب تحج به، وتعتمر به، هذا أكمل وأفضل، وإذا حججت مع غيرك؛ مع الجامعة، أو مع غير الجامعة، أو مع أبيك، أو من مال أبيك المخلوط؛ فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11898/حكم-الذهاب-الى-العمرة-على-نفقة-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52213.mp3","categories":["حكم الحج والعمرة"]},{"id":13812,"question":"هذا يجعلنا نسأل سماحة الشيخ: ما حكم ترك الحج مع القدرة عليه؟","title":"حكم ترك الحج مع الاستطاعة","answer":"الجواب: حكمه أنه معصية، الله قال: مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا[آل عمران:97]، فلا يجوز للمسلم أن يؤخر الحج وهو قادر، بل يجب أن يبادر، هذا هو الصواب، أنه على الفور، فإذا استطاع الحج وجب أن يبادر، وإذا كان عليه دين يبدأ بأهل الدين إلا إذا سمحوا. نعم.","link":"https://binbaz.org.sa/fatwas/12180/حكم-ترك-الحج-مع-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53624.mp3","categories":["حكم الحج والعمرة"]},{"id":14140,"question":"السائل أبو أحمد له مجموعة من الأسئلة يقول في هذا  ما حكم العمرة، وهل هي واجب على الإنسان في العمر أم أنها سنة؟","title":"ما حكم العمرة؟","answer":"الجواب: العمرة واجبة على كل مكلف استطاع ذلك على الصحيح من قولي العلماء أن العمرة تجب على الذكر والأنثى المكلفين إذا استطاعا ذلك كالحج؛ لقوله ﷺ في حديث عمر لما سأله عن الإسلام قال: أن تشهد أن لا إله إلا الله وأن محمدًا رسول الله، وأن تقيم الصلاة وتؤتي الزكاة، وتصوم رمضان وتحج وتعتمر أخرجه الدارقطني وابن خزيمة بإسناد صحيح، وقال لـعائشة رضي الله عنها: على النساء جهاد لا قتال فيه: الحج والعمرة. فالحج والعمرة واجبان على الرجال والنساء مرة في العمر مع الاستطاعة، هذا هو الصواب، ويدخل في هذا أهل مكة وغيرهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12581/ما-حكم-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54605.mp3","categories":["حكم الحج والعمرة"]},{"id":14154,"question":"إذا أتى الشخص إلى مكة المكرمة لأداء الحج أو العمرة فهل يجوز له بعد الانتهاء من حجته أو عمرته أن يؤدي عمرة أخرى له أو لغيره في نفس هذا الموسم الذي أتى فيه، بحيث يخرج من مكة إلى التنعيم للإحرام ثم يقضي هذه العمرة؟ أرجو الإفادة بارك الله فيكم.","title":"حكم تكرار العمرة في نفس الموسم","answer":"الجواب: لا حرج في ذلك والحمد لله إذا قدم للعمرة أو للحج فحج عن نفسه أو اعتمر عن نفسه أو حج عن غيره أو اعتمر عن غيره وأحب أن يأخذ عمرة أخرى لنفسه أو لغيره فلا حرج في ذلك، لكن يأخذها من الحل يخرج من مكة إلى الحل، التنعيم أو الجعرانة أو غيرهما فيحرم من هناك ثم يدخل فيطوف ويسعى ويقصر، سواء عن نفسه أو عن ميت من أقاربه وأحبابه أو عن عاجز شيخ كبير أو عجوز كبيرة عاجزين عن العمرة فلا بأس.\nوقد فعلت هذا عائشة بأمر النبي ﷺ فإنها اعتمرت مع النبي ﷺ ثم استأذنت في ليلة الحصبة ليلة ثلاثة عشر.. ليلة أربعة عشر استأذنت بل ليلة ثلاثة عشر استأذنت في ليلة الحصبة وهي مساء اليوم الثالث ليلة أربعة عشر استأذنت أن تعتمر فأذن لها عليه الصلاة والسلام، وأمر عبد الرحمن بن أبي بكر وهو أخوها أن يذهب معها إلى التنعيم فاعتمرت رضي الله عنها، وهذه عمرة ثانية من داخل مكة.\nفالحاصل: أنه لا حرج أن يؤدي الإنسان الحج عن نفسه أو العمرة عن نفسه ثم يعتمر لشخص آخر أو يعتمر عن غيره أو يحج عن غيره ثم يعتمر لنفسه لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا. إذا كانت العمرة الأولى والثانية لنفسه فهل تشترطون فاصلًا زمنيًا معينًا؟\nالشيخ: ليس هناك دليل، بعض أهل العلم كره تقارب العمرتين لكن ليس عليه دليل، يقول النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة متفق على صحته، ولم يقل: بينهما كذا ولا كذا، وعائشة رضي الله عنها اعتمرت بعد عمرتها الأولى بأقل من عشرين يومًا، اعتمرت في أول ذي الحجة .. في آخر.. لبت بالعمرة في آخر ذي القعدة من المدينة وكملت حجها مع النبي ﷺ قارنة؛ لأنها منعها الحيض من أداء العمرة فحجت قارنة، ثم استأذنت في العمرة الجديدة في ليلة الحصبة ليلة أربعة عشر وقالت: \"إنكم تنطلقون بحجة وعمرة -يعني: مفردين- وأنا أنطلق بحج\" يعني: حج معه عمرة مقرونة فأذن لها النبي ﷺ واعتمرت.\nالمقصود: ليس على اشتراط مدة بين العمرتين ليس هناك دليل واضح، وإطلاق النبي ﷺ حين قال: العمرة إلى العمرة كفارة لما بينهما يعم القليل والكثير، لكن إذا كان هناك زحمة أو مشقة فالأولى ترك ذلك حتى لا يشق على غيره أيام الحج يكون مشقة فإذا كثر المعتمرون شقوا على الناس فترك ذلك أولى؛ ولأن النبي ﷺ وأصحابه لم يعتمروا بعد الحج ما عدا عائشة، بل سيكتفوا بعمرتهم الأولى فإذا تأسى بهم المؤمن وترك العمرة هذا أفضل، وإن اعتمر بعدما يخف الناس وتقل الزحمة فلا حرج في ذلك.\nالمقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12595/حكم-تكرار-العمرة-في-نفس-الموسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48505.mp3","categories":["حكم الحج والعمرة"]},{"id":14212,"question":"يقول: ذهبت إلى الحج وكان لدي أقارب هناك يحتاجون إلى المال فسمعت من بعض الإخوة بأنهم يقولون: لو أنك أعطيتهم المال وكنت ناوي للحج يسقط عنك الحج، هل هذا الكلام صحيح أم لا؟","title":"هل الصدقة تسقط فريضة الحج؟","answer":"الجواب: لا، هذا كلام باطل، الصدقة لا تسقط الحج، الحج باقي، عليه أن يحج وعليه أن ينفق على الفقراء من أقاربه إذا استطاع ذلك من باب صلة الرحم، والحج لا يسقط بالنفقة يجب عليه أن يحج مقدمًا على الصدقة، يجب أن يحج إذا كان عنده قدرة على الحج. نعم.","link":"https://binbaz.org.sa/fatwas/12661/هل-الصدقة-تسقط-فريضة-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54813.mp3","categories":["حكم الحج والعمرة"]},{"id":15393,"question":"يستفسر عن معنى الآية الكريمة في سورة البقرة: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196]؟","title":"معنى قوله تعالى: {وأتموا الحج والعمرة لله}","answer":"الجواب: على ظاهرها، يجب على من دخل فيهما أن يتمهما؛ من أحرم بالحج يجب عليه أن يكمل، ومن أحرم بالعمرة يجب عليه أن يكمل، إلا إذا اشترط قال: إن حبسني حابس، فهو على شرطه، وإلا فالواجب أنه إذا دخل في الحج يكمل، وإذا دخل في العمرة يكمل.","link":"https://binbaz.org.sa/fatwas/13895/معنى-قوله-تعالى-واتموا-الحج-والعمرة-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56718.mp3","categories":["التفسير","حكم الحج والعمرة"]},{"id":16284,"question":"من الأردن المستمع محمد إبراهيم عبداللطيف من جامعة مؤتة رسالة، وضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: أردت الحج، أو العمرة، وكان على والدي دين، وأنا ابنه، وليس لي مخصص، أو دخل لي أنا خاصة، فهل حجي مقبول، أو عمرتي؟","title":"حكم حج الولد إذا كان على أبيه دين","answer":"الجواب: إن كان مالك من مال أبيك؛ فقدم دين أبيك؛ اقض دينه، أما إن كان مالك من غير مال أبيك، مما كسبته أنت؛ فقدم الحج، ولا يلزمك قضاء دين أبيك، قدم الحج، وأد الحج؛ لأنه فرض عليك، أنت مستطيع، فإن يسر الله لك قضاء دين أبيك؛ فهذا بر، وإلا فلا يلزمك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14984/حكم-حج-الولد-اذا-كان-على-ابيه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80908.mp3","categories":["حكم الحج والعمرة"]},{"id":16632,"question":"يقول في قضية هامة سماحة الشيخ: أنا وصلت من بلدي لأداء العمرة، واعتمرت، ثم ذهبت إلى المدينة للزيارة، وجلست في المدينة أسترزق عدة شهور، ثم جاء وقت الحج، وأريد أن أحج، فما هو الحكم في عملي هذا، ولاسيما أني قدمت فقط للعمرة، والزيارة، جزاكم الله خيرًا؟","title":"حكم الحج لمن قدم من بلده للعمرة والزيارة","answer":"الجواب: الحمد لله، تحج من المدينة، والحمد لله، هذا من فضل الله عليك أنه يسر لك الحج، تحرم من ميقات المدينة بالحج، والحمد لله، وإن أخذت عمرة ثانية من ميقات المدينة، ثم يوم الثامن من ذي الحجة تلبي بالحج مع الناس، يكون أفضل، وتكون متمتعًا، وعليك الدم ذبيحة واحدة، تذبحها يوم النحر، أو أيام العيد، أو سبع بدنة، أو سبع بقرة، هذا هو الواجب على المتمتع. وإن أحرمت بحج مفردٍ فلا بأس، لكن الأفضل لك أن تحرم بالعمرة، هذا هو السنة، تطوف، تسعى، تقصر؛ تحل، ثم في اليوم الثامن بعد ذلك في اليوم الثامن عند الذهاب إلى منى تلبي بالحج، هذا هو الذي أرشد النبي ﷺ إليه أصحابه لما قدموا من المدينة في حجة الوداع، أمرهم أن يحلوا، ويجعلوها عمرة إلا من كان معه الهدي، إلا من ساق الهدي من المدينة، أو من الطريق هذا يبقى على إحرامه، أما الذي لبى بالحج، أو بالحج والعمرة جميعًا، وليس معه هدي فالرسول ﷺ أمرهم أن يحلوا بالطواف، والسعي، والتقصير، ويجعلوها عمرة، ثم يلبون بالحج يوم الثامن، وقد فعلوا -رضي الله عنهم- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15365/حكم-الحج-لمن-قدم-من-بلده-للعمرة-والزيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71611.mp3","categories":["حكم الحج والعمرة"]},{"id":16668,"question":"السائلة أم عبدالله تقول: بعض النساء تقول: بأن حجتها الأولى ما أقنعتها، حيث حجت في أعوام سابقة، وترى أن تعيدها بسبب كثرة الأخطاء التي حصلت في أعوام سابقة، فهل تجزئها الحجة الأولى؟","title":"حكم الحج مرة أخرى لمن شك في حجه الأول","answer":"الجواب:  حج النافلة مطلوب، كونها تحج نافلة مرة، أو مرتين كله مطلوب طيب الحمد لله، أما الحجة الأولى ينظر فيها، عليها أن تبين الأسباب التي أشكلت عليها حتى ينظر فيها، أما دعواها لصحيح، وما هو صحيح ما نعلم الغيب، الغيب لا يعلمه إلا الله، لكن عليها أن تبين ما وقع لها من الإشكال حتى تجاب، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15401/حكم-الحج-مرة-اخرى-لمن-شك-في-حجه-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58402.mp3","categories":["حكم الحج والعمرة"]},{"id":16719,"question":"هذا السائل فهد من حائل يقول: سماحة الشيخ! أبلغ من العمر الثانية والأربعين، وحتى الآن لم أقض فريضة الحج، وذلك لأسباب، وهي أني قصير القامة، وضعيف الجسم، ولا أستطيع المشي، وجهوني في ضوء هذا السؤال؟","title":"ما حكم الحج على من لا يستطيع المشي؟","answer":"الجواب: عليك أن تحج، ولو كنت صغير القامة، والماشي ما يمنع، تطوف بالعربة عنه، والحمد لله، العربية، تطوف بالعربية، والحمد لله، وتسعى فيها، واستعن بالله إذا كنت قادرًا من جهة المال. المقدم: سماحة الشيخ هل له أن يوكل؟ الشيخ: لا، عليه أن يحج بنفسه، ما دام في حال ..... يحج بنفسه؛ لأن المشي ما يمنع، ضعف المشي ما يمنع، نعم، يمكن يركب في السيارة، أو في الطائرة، أو يحمل في العربية، ينتقل بالعربية في الطواف والسعي، الحمد لله، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15459/ما-حكم-الحج-على-من-لا-يستطيع-المشي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58425.mp3","categories":["حكم الحج والعمرة"]},{"id":18293,"question":"تسأل أختنا وتقول: أنا في الواحدة والعشرين من عمري، ولي أخت تعمل بالخارج عرضت علي أن أؤدي فريضة الحج على نفقتها، فهل هذا جائز شرعًا؟ مع العلم أنني لا أعمل، وليس لي مال، أرجو التوضيح؟ جزاكم الله خيرًا.","title":"حكم أداء الحج على نفقة شخص ما","answer":"الجواب: نعم، لا بأس بذلك، إذا التزمت أختك بالنفقة فجزاها الله خيرًا، الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه. ويقول عليه الصلاة والسلام: من كان في حاجة أخيه كان الله في حاجته متفق عليه، فإذا التزمت أختك أو أخوك أو عمك أو خالك، أو أبوك، أو أمك بالنفقة فجزاهم الله خيرًا، ولا شيء عليك ولا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/17344/حكم-اداء-الحج-على-نفقة-شخص-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91208.mp3","categories":["حكم الحج والعمرة"]},{"id":18809,"question":"هل يجوز الحج قبل الوالدين؟ وإذا كان أحد الوالدين مصاب بمرض عقلي هل يجوز الحج عنه؟أفيدونا أثابكم الله.","title":"حكم حج الولد قبل والديه والحج عن فاقد العقل منهما","answer":"الجواب: لا حرج أن يحج الإنسان قبل والده، لا بأس أن يحج قبل أمه، وقبل أبيه؛ لأنه قد يتيسر له الحج ولا يتيسر لهما، فلا حرج في ذلك، ولا نعلم خلافًا في هذا بين أهل العلم. وإذا كان الوالد مجنونًا، أو فاقد العقل من غير جنون؛ فلا بأس أن يحج عنه، أن يحج عنه ولده برًا له، سواء كان الوالد أبًا أو أمًا؛ لأن الحج الذي لا يصح من المجنون إذا باشره بنفسه، ما يصح حج المجنون والمعتوه إذا باشره بنفسه، أما إذا كان حج عنه غيره فلا بأس بذلك، وليس عليه حج فريضة، إذا بلغ وهو مجنون لا حج عليه، لكن لو حج عنه ولده، أو أخوه أو غيرهما؛ فلا بأس، وله أجر ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17934/حكم-حج-الولد-قبل-والديه-والحج-عن-فاقد-العقل-منهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87609.mp3","categories":["النيابة في الحج","حكم الحج والعمرة"]},{"id":19146,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (م. أ . ......) يقول: سمعت من بعض الناس يقول: إن الحج قبل الزواج لا يصح فريضة، بل لابد من تأدية الفريضة بعد الزواج فهل هذا صحيح؟","title":"حكم الحج قبل الزواج","answer":"الجواب: ليس بصحيح، الحج يجوز قبل الزواج وبعد الزواج، إذا كان قد بلغ الحلم حجه صحيح ويؤدي عنه الفريضة، أما إذا حج قبل أن يبلغ فإنه يكون نافلة، ومتى حج بعد هذا وأدى الحج على وجهه الشرعي حجه صحيح، ويؤدى عنه الفريضة ولو لم يتزوج. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18317/حكم-الحج-قبل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73710.mp3","categories":["حكم الحج والعمرة"]},{"id":19697,"question":"ما حكم الحج للشَّاب الذي لم يحجّ حجَّة الإسلام إذا رفض والده؟","title":"حكم من يمنعه والده من أداء حجة الإسلام","answer":"الجواب: إذا كان يستطيع الحجَّ عليه أن يحج ولو مرةً ثانيةً؛ لأنَّ الله جلَّ وعلا قال: وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12]، إذا كان الرسولُ لا يُعصى في معروفٍ، كذلك الناس من باب أولى لا يعصون في معروف، لكن يعصون في غير المعروف: إنما الطاعة في المعروف، فإذا أمره والده بأن لا يحجَّ وهو يستطيع الحجَّ فإنَّ عليه أن يحج. أما إذا كان والده هو يحججه يقول له: لا، اصبر، أنا أُحججك الحين، وما عليه شيء، يصبر؛ لأنه فقير. أما إذا كان قادرًا -عنده مال ويستطيع أن يحجَّ- ويقول له: لا تحجَّ، لا، إنما الطاعة بالمعروف، لكن يُخاطبه بالتي هي أحسن، ويتلطف بالكلام معه، أو يستعين بإخوانه الكبار، أو بأعمامه، أو بأخواله، حتى يتوسّل إلى والده بالسماح، وحتى لا يكون بينه وبين والده وحشة، ولا هجران، يعني: يفعل ما يستطيع من فعل الطيب مع والده، فإذا أصرَّ إصرارًا لم ينفع فيه شيءٌ؛ حجَّ ولو لم يُطع، إذا كان يستطيع.","link":"https://binbaz.org.sa/fatwas/20542/حكم-من-يمنعه-والده-من-اداء-حجة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0507%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA%20%D9%84%D9%84%D8%B4%D9%8A%D8%AE%20%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2%20%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D8%B1%D8%AD%D9%85%D9%87%20%D8%A7%D9%84%D9%84%D9%87.mp3","categories":["حكم الحج والعمرة"]}]
